    "text": "교보생명의 3분기 누적 연결 순이익은 7,082억 원으로 19.9% 줄었어요. 반면 9월 말 보유 보험계약마진은 7조 587억 원으로 새 회계기준 도입 이후 처음 7조 원을 넘었고, 3분기 연결 보험손익은 1,851억 원으로 10.8% 늘었어요.",
