    "text": "올해 상반기 부지급 건수는 2만 9,100건으로 18.6% 줄었지만 보험금 지급액은 6,276억 원으로 2.2% 늘었어요. 5세대 실손이 5월 6일 출시돼 상반기 통계 영향은 제한적이라고 해요.",
