    "text": "한화생명, 한화손해보험, 한화투자증권, 한화자산운용이 10월 30일 63빌딩에서 임직원 140여 명이 모인 가운데 퇴직연금 비전 선포식을 열었어요. 500조 원을 넘은 퇴직연금 시장에서 기금형 도입에 대비해 운용 역량, 지배구조와 내부통제, 상품·디지털 경쟁력을 키우겠다고 밝혔어요.",
    "point": "'기금형이 열리면 보험사의 강점은?'이라는 질문으로 이어서 생각해볼 수 있어요. 종신연금처럼 장수 위험을 맡는 상품과 연결해 보면 좋아요.",
    "source": {
      "name": "허프포스트코리아",
      "url": "https://www.huffingtonpost.kr/article/261720"
    },
    "issue": "2026-11-02-2"
