    "text": "신한라이프의 3분기 누적 순이익은 4,194억 원으로 18.5% 줄었고 보험손익(−17.3%)과 투자손익(−25.7%)이 함께 줄었어요. 동양생명은 보험손익이 1,340억 원으로 41.1% 늘었지만 투자손익이 420억 원 적자로 돌아섰어요.",
    "point": "금리 상승이 채권 평가와 처분이익을 줄여 투자손익을 압박했다는 점을 보험손익과 나눠 설명하면 좋아요.",
