    "text": "롯데손해보험 공개매각 공고가 9월 말에서 10월 말로 연기됐어요. 대주주 제이케이엘파트너스는 1조 원 안팎을 원하지만 신한금융은 7천억~8천억 원 수준을 검토해 왔고, 2분기 말 전체 지급여력비율(킥스)은 161.9%인데 기본자본 비율은 −5.4%라 인수자가 자본을 더 넣어야 해요. 기본자본 비율이 47.6%로 권고 수준 50%에 못 미치는 흥국화재는 자본확충 부담으로 인수전에 빠지는 쪽으로 알려졌어요.",
    "point": "전체 지급여력비율은 높아도 기본자본 비율이 마이너스일 수 있다는 점을 짚으며, 자본의 질이 인수가격과 증자 부담에 어떤 영향을 주는지 설명할 수 있어요.",
