    "text": "9월 가입 가능 여부와 대안 상품을 미리 안내하는 시스템의 특허를 등록했어요. 매년 9월 셋째 주 목요일을 금융소비자의 날로 정하고, 3월부터 소비자보호 교육을 100회차 넘게 진행했어요.",
